import{_ as a,o as l,c as o,a4 as e}from"./chunks/framework.vNSRaLQv.js";const _=JSON.parse('{"title":"失败记录 - 2026-07-19","description":"","frontmatter":{"title":"失败记录 - 2026-07-19","date":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"posts/失败记录.md","filePath":"posts/失败记录.md"}'),t={name:"posts/失败记录.md"};function r(n,i,s,d,h,c){return l(),o("div",null,[...i[0]||(i[0]=[e('<h1 id="失败记录-2026-07-19" tabindex="-1">失败记录 - 2026-07-19 <a class="header-anchor" href="#失败记录-2026-07-19" aria-label="Permalink to &quot;失败记录 - 2026-07-19&quot;">​</a></h1><h2 id="环境" tabindex="-1">环境 <a class="header-anchor" href="#环境" aria-label="Permalink to &quot;环境&quot;">​</a></h2><ul><li><strong>主机</strong>: AMD Lucienne APU (Ryzen 5 5500U), 14GB RAM</li><li><strong>系统</strong>: Debian 13 (Linux)</li><li><strong>虚拟机磁盘</strong>: <code>/home/a1/win11.qcow2</code> (Windows 11 不忘初心精简版)</li><li><strong>外接盘</strong>: <code>/dev/sda</code> (K5-60G, 60GB SSD, Windows 系统盘)</li></ul><h2 id="尝试-1-重建-windows-vm-qxl-显示" tabindex="-1">尝试 1：重建 Windows VM（QXL 显示） <a class="header-anchor" href="#尝试-1-重建-windows-vm-qxl-显示" aria-label="Permalink to &quot;尝试 1：重建 Windows VM（QXL 显示）&quot;">​</a></h2><ul><li>使用 virt-manager 安装 win11.qcow2</li><li>磁盘用 virtio → 蓝屏（INACCESSIBLE_BOOT_DEVICE）</li><li>改为 SATA → 成功进桌面</li><li>精简版系统无法安装 QXL 显卡驱动（不包含 Win10/11 驱动安装功能）</li></ul><h2 id="尝试-2-vmware-svga-显示" tabindex="-1">尝试 2：VMware SVGA 显示 <a class="header-anchor" href="#尝试-2-vmware-svga-显示" aria-label="Permalink to &quot;尝试 2：VMware SVGA 显示&quot;">​</a></h2><ul><li>把显示从 QXL 改为 vmvga（Windows 自带 VMware SVGA 驱动）</li><li>可以显示，但依然没有 2D 加速</li></ul><h2 id="尝试-3-外接硬盘直通" tabindex="-1">尝试 3：外接硬盘直通 <a class="header-anchor" href="#尝试-3-外接硬盘直通" aria-label="Permalink to &quot;尝试 3：外接硬盘直通&quot;">​</a></h2><ul><li>外接盘 <code>/dev/sda</code> 连接到 VM</li><li>第一次成功启动，进入 Windows 桌面</li><li>尝试修改 CPU 配置（host-model）→ Windows 触发自动修复</li><li>重建 VM（virt-install 重新定义）→ 未加 snapshot 只读保护，外接盘被写入</li><li>后续重启仍然无法进入系统，自动修复死循环</li></ul><h2 id="根本问题" tabindex="-1">根本问题 <a class="header-anchor" href="#根本问题" aria-label="Permalink to &quot;根本问题&quot;">​</a></h2><ol><li><strong>笔记本单 GPU 无法直通</strong>（IOMMU 分组、复位 bug、无第二 GPU）</li><li><strong>Windows 精简版不能安装标准驱动</strong>（QXL/virtio 驱动安装器不可用）</li><li><strong>外接盘物理转虚拟</strong>后硬件变更触发 Windows 自动修复，且 VM 配置变更加剧问题</li><li><strong>系统重启 libvirtd</strong>时 service 卡死 zombie 进程，需硬重启</li></ol><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><ul><li>不直通的情况下，Windows 虚拟机只能有 2D 基础显示（无硬件加速）</li><li>外接盘 Windows 即使第一次能进，硬件变更也会导致后续启动失败</li><li>任何 VM 配置变更（CPU 型号等）都会让 Windows 触发修复流程</li></ul>',13)])])}const m=a(t,[["render",r]]);export{_ as __pageData,m as default};
